use serde_json::Value;

pub fn solve(input: Value) -> Value {
    let input_i64 = input.as_i64().unwrap();
    let sign = if input_i64 < 0 { "-" } else { "" };
    let magnitude = input_i64.abs();
    let pounds = format!("{:.2}", magnitude as f64 / 100.0);
    let mut output = Value::String(format!("{} {}", sign, pounds));
    output
}
